const raw = $input.first().json;
const arr = Array.isArray(raw) ? raw : [raw];
return arr.filter(j => j.position || j.title).map(j => ({ json: { ...j, _source: 'remoteok' } }));

const data = $input.first().json;
const jobs = data.jobs || data || [];
return (Array.isArray(jobs) ? jobs : []).map(j => ({ json: { ...j, _source: 'remotive' } }));

// Wellfound returns HTML or JSON depending on headers. Parse what we get.
const raw = $input.first().json;
if (Array.isArray(raw)) {
  return raw.map(j => ({ json: { ...j, _source: 'wellfound' } }));
}
if (raw.jobs) {
  return raw.jobs.map(j => ({ json: { ...j, _source: 'wellfound' } }));
}
// If HTML, return a placeholder so workflow doesn't break
console.log('Wellfound: no structured data found. Check node config or replace with scraper.');
return [];

const raw = $input.first().json;
if (Array.isArray(raw)) return raw.map(j => ({ json: { ...j, _source: 'yc' } }));
if (raw.jobs) return raw.jobs.map(j => ({ json: { ...j, _source: 'yc' } }));
console.log('YC: no structured data. Consider using Apify YC scraper actor.');
return [];

const raw = $input.first().json;
if (Array.isArray(raw)) return raw.map(j => ({ json: { ...j, _source: 'otta' } }));
if (raw.jobs) return raw.jobs.map(j => ({ json: { ...j, _source: 'otta' } }));
console.log('Otta: no structured data. Consider Apify actor.');
return [];

const items = $input.all();
const result = [];

for (const item of items) {
  const d = item.json;
  const src = d._source || 'unknown';
  let job = {};

  if (src === 'remoteok') {
    job = {
      job_title: d.position || d.title || '',
      company: d.company || '',
      job_url: d.url || d.apply_url || '',
      source: 'Remote OK',
      location_text: d.location || 'Worldwide',
      salary: d.salary_min ? `$${d.salary_min}-${d.salary_max}` : '',
      description: (d.description || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.date || '',
      tags: Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || '')
    };
  } else if (src === 'remotive') {
    job = {
      job_title: d.title || '',
      company: d.company_name || '',
      job_url: d.url || '',
      source: 'Remotive',
      location_text: d.candidate_required_location || 'Worldwide',
      salary: d.salary || '',
      description: (d.description || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.publication_date || '',
      tags: Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || '')
    };
  } else if (src === 'wwr') {
    job = {
      job_title: d.title || '',
      company: d.author || d['dc:creator'] || '',
      job_url: d.link || '',
      source: 'We Work Remotely',
      location_text: 'Worldwide',
      salary: '',
      description: (d.content || d.contentSnippet || d.description || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.isoDate || d.pubDate || '',
      tags: Array.isArray(d.categories) ? d.categories.join(', ') : ''
    };
  } else if (src === 'himalayas') {
    job = {
      job_title: d.title || '',
      company: d.author || '',
      job_url: d.link || '',
      source: 'Himalayas',
      location_text: 'Worldwide',
      salary: '',
      description: (d.content || d.contentSnippet || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.isoDate || '',
      tags: Array.isArray(d.categories) ? d.categories.join(', ') : ''
    };
  } else if (src === 'dynamite') {
    job = {
      job_title: d.title || '',
      company: d.author || '',
      job_url: d.link || '',
      source: 'Dynamite Jobs',
      location_text: 'Remote',
      salary: '',
      description: (d.content || d.contentSnippet || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.isoDate || '',
      tags: Array.isArray(d.categories) ? d.categories.join(', ') : ''
    };
  } else if (src === 'wellfound') {
    job = {
      job_title: d.title || d.name || '',
      company: d.startup_name || d.company || '',
      job_url: d.job_url || d.url || '',
      source: 'Wellfound',
      location_text: Array.isArray(d.location_names) ? d.location_names.join(', ') : (d.location || 'Remote'),
      salary: d.compensation || d.salary || '',
      description: (d.description || d.job_description || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.created_at || '',
      tags: Array.isArray(d.skills) ? d.skills.join(', ') : (d.tags || '')
    };
  } else if (src === 'yc') {
    job = {
      job_title: d.title || d.role_title || d.role || '',
      company: d.company_name || d.startup_name || d.company || '',
      job_url: d.apply_url || d.url || d.link || '',
      source: 'Y Combinator',
      location_text: Array.isArray(d.locations) ? d.locations.join(', ') : (d.location || 'Remote'),
      salary: d.equity || d.compensation || '',
      description: (d.description || d.job_description || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.created_at || '',
      tags: Array.isArray(d.skills) ? d.skills.join(', ') : (d.tags || '')
    };
  } else if (src === 'otta') {
    job = {
      job_title: d.title || d.job_title || '',
      company: d.company || d.company_name || '',
      job_url: d.url || d.link || '',
      source: 'Otta',
      location_text: d.location || 'Remote',
      salary: d.salary || '',
      description: (d.description || d.body || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.created_at || d.posted_at || '',
      tags: d.tags || ''
    };
  } else {
    job = {
      job_title: d.title || d.job_title || d.position || '',
      company: d.company || d.company_name || d.employer || '',
      job_url: d.url || d.link || d.job_url || '',
      source: src,
      location_text: d.location || d.location_text || '',
      salary: d.salary || d.compensation || '',
      description: (d.description || d.body || '').replace(/<[^>]+>/g, '').substring(0, 2000),
      posted_date: d.date || d.created_at || d.posted_date || '',
      tags: d.tags || ''
    };
  }

  job.job_id = job.job_url
    ? job.job_url.replace(/[^a-z0-9]/gi, '_').toLowerCase().substring(0, 100)
    : `${(job.company||'').toLowerCase()}_${(job.job_title||'').toLowerCase()}`.replace(/[^a-z0-9]/gi, '_').substring(0, 100);

  if (job.job_title && (job.job_url || job.company)) {
    result.push({ json: job });
  }
}

return result;

// items from Google Sheets (existing records)
const existing = $input.all();
// new normalized jobs from earlier in pipeline
const newJobs = $('Normalize Job Data').all();

const existingUrls = new Set(
  existing.map(i => (i.json.job_url || '')).filter(Boolean)
);
const existingKeys = new Set(
  existing.map(i => `${(i.json.company||'').toLowerCase()}|||${(i.json.job_title||'').toLowerCase()}`)
    .filter(k => k !== '|||')
);

const seenUrls = new Set();
const seenKeys = new Set();
const unique = [];

for (const item of newJobs) {
  const j = item.json;
  const url = (j.job_url || '').trim();
  const key = `${(j.company||'').toLowerCase()}|||${(j.job_title||'').toLowerCase()}`;

  if (url && (existingUrls.has(url) || seenUrls.has(url))) continue;
  if (!url && (existingKeys.has(key) || seenKeys.has(key))) continue;

  if (url) seenUrls.add(url);
  seenKeys.add(key);
  unique.push(item);
}

console.log(`Dedup: ${newJobs.length} new → ${unique.length} after dedup (removed ${newJobs.length - unique.length} duplicates)`);
return unique;

const REJECT = [
  /\bus[\s-]only\b/i, /\bunited\s+states[\s-]only\b/i,
  /\bcanada[\s-]only\b/i, /\buk[\s-]only\b/i,
  /\beu[\s-]only\b/i, /\beurope[\s-]only\b/i,
  /\baustralia[\s-]only\b/i, /\bmust\s+be\s+based\s+in\b/i,
  /\bmust\s+live\s+in\b/i, /\bmust\s+reside\s+in\b/i,
  /\bauthorized\s+to\s+work\s+in\s+the\s+(?:us|uk|eu|usa)\b/i,
  /\blocal\s+work\s+permit\s+required\b/i,
  /\bhybrid\b/i, /\bon[-\s]?site\b/i, /\boffice[-\s]required\b/i,
  /\bin[-\s]person\b/i, /\bremote\s+within\s+\w+\s+only\b/i,
  /\bfixed\s+us\s+hours\b/i, /\bfixed\s+eu\s+hours\b/i,
  /\bmust\s+work\s+(?:us|est|pst|cst|cet)\s+hours\b/i,
  /\bno\s+international\b/i, /\bdomestic\s+only\b/i,
  /\bopen\s+to\s+(?:us|uk|eu|canada|australia)\s+(?:only|residents|citizens)\b/i
];

const POSITIVE = [
  /\bworldwide\s+remote\b/i, /\bglobal\s+remote\b/i,
  /\bwork\s+from\s+anywhere\b/i, /\banywhere\s+in\s+the\s+world\b/i,
  /\bopen\s+to\s+anyone\b/i, /\bapac\s+(?:remote|friendly|ok)\b/i,
  /\binternational\s+contractor/i, /\bb2b\s+contractor\b/i,
  /\bcontracting\s+worldwide\b/i, /\bdeel\b/i,
  /\boyster\s+hr\b/i, /\bremote\.com\b/i,
  /\beor\s+supported\b/i, /\bemployer\s+of\s+record\b/i,
  /\bremote[-\s]first\b/i, /\bfully\s+distributed\b/i,
  /\bno\s+location\s+restriction/i
];

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const j = item.json;
  const text = `${j.job_title} ${j.location_text} ${j.description} ${j.tags}`;

  if (REJECT.some(p => p.test(text))) {
    rejected.push(j.job_title);
    continue;
  }

  const hasPositive = POSITIVE.some(p => p.test(text));
  item.json._hard_filter_signal = hasPositive ? 'positive' : 'neutral';
  passed.push(item);
}

console.log(`Hard filter: ${passed.length} passed, ${rejected.length} rejected`);
return passed;

const SYSTEM_PROMPT = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says 'remote.'

REJECT if the job:
- Requires the worker to live in US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- Requires local work authorization outside Taiwan
- Is hybrid, onsite, or remote within one country only
- Requires fixed working hours that would force Jerry to work through the night in Taiwan (e.g. 9am-5pm EST means 9pm-5am Taiwan time)

KEEP only if:
- The job says worldwide remote, work from anywhere, global remote
- The job says APAC remote
- The job allows international contractors anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or contractor agreement
- No country restriction is mentioned and the role is contractor/freelance-friendly

Return ONLY valid JSON, nothing else:
{
  "taiwan_eligible": "yes|no|unclear",
  "reason": "short reason (max 20 words)",
  "location_risk": "low|medium|high",
  "timezone_risk": "low|medium|high",
  "contractor_possible": "yes|no|unclear",
  "decision": "keep|reject|manual_check"
}`;

return $input.all().map(item => {
  const j = item.json;
  const jobText = [
    `Title: ${j.job_title}`,
    `Company: ${j.company}`,
    `Source: ${j.source}`,
    `Location field: ${j.location_text}`,
    `Tags: ${j.tags}`,
    `Salary: ${j.salary || 'not listed'}`,
    `Signal: ${j._hard_filter_signal}`,
    `\nDescription:\n${(j.description || '').substring(0, 1800)}`
  ].join('\n');

  return {
    json: {
      _original_job: j,
      _system_prompt: SYSTEM_PROMPT,
      _user_content: `Evaluate this job for Taiwan eligibility:\n\n${jobText}`
    }
  };
});

const items = $input.all();

return items.map(item => {
  let ai = {
    taiwan_eligible: 'unclear',
    reason: 'no response',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };

  try {
    const content = item.json.choices?.[0]?.message?.content
      || item.json.message?.content
      || item.json.content
      || '{}';
    const cleaned = content.replace(/```(?:json)?\n?|\n?```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    if (parsed.taiwan_eligible) ai = parsed;
  } catch(e) {
    console.log('AI parse error:', e.message);
  }

  const originalJob = item.json._original_job || {};

  return {
    json: {
      ...originalJob,
      taiwan_eligible: ai.taiwan_eligible || 'unclear',
      taiwan_reason: ai.reason || '',
      location_risk: ai.location_risk || 'medium',
      timezone_risk: ai.timezone_risk || 'medium',
      contractor_possible: ai.contractor_possible || 'unclear',
      ai_decision: ai.decision || 'manual_check'
    }
  };
}).filter(item => item.json.ai_decision !== 'reject');

const ASYNC_HIGH = [
  /\basync\b/i, /\basynchronous\b/i,
  /\bno\s+(?:required\s+)?meetings\b/i, /\bmeeting[-\s]free\b/i,
  /\bflexible\s+hours\b/i, /\bflexible\s+schedule\b/i,
  /\bwork\s+on\s+your\s+own\s+time\b/i, /\bset\s+your\s+own\s+hours\b/i,
  /\bno\s+fixed\s+hours\b/i
];

const ASYNC_MED = [
  /\bdistributed\s+team\b/i, /\bremote[-\s]first\b/i,
  /\blow\s+meeting\s+culture\b/i, /\bwork\s+across\s+time\s+zones\b/i,
  /\bglobal\s+team\b/i, /\bflexible\s+work/i,
  /\btime\s+zone\s+flexible\b/i, /\bfully\s+remote\b/i
];

const SYNC_REJECT = [
  /\bstrict\s+9[-\s]to[-\s]5\b/i,
  /\bfixed\s+(?:us|est|pst|cst|cet|gmt[-+]\d)\s+hours\b/i,
  /\bdaily\s+live\s+calls?\s+required\b/i,
  /\bmust\s+(?:be\s+)?overlap\s+(?:full\s+)?(?:us|eu|est|pst)\s+business\s+hours\b/i,
  /\brequired.*(?:9am|9:00).*(?:5pm|17:00).*(?:est|pst|cet|gmt)\b/i
];

const ASYNC_KEYWORDS = [
  'async', 'asynchronous', 'flexible hours', 'flexible schedule',
  'distributed team', 'remote first', 'remote-first', 'work from anywhere',
  'low meeting', 'no daily standups'
];

return $input.all().map(item => {
  const text = `${item.json.job_title} ${item.json.description} ${item.json.tags} ${item.json.location_text}`;

  const syncRejected = SYNC_REJECT.some(p => p.test(text));
  if (syncRejected) return null;

  const asyncHigh = ASYNC_HIGH.some(p => p.test(text));
  const asyncMed = ASYNC_MED.some(p => p.test(text));
  const asyncLevel = asyncHigh ? 'high' : asyncMed ? 'medium' : 'low';
  const asyncKeywordsFound = ASYNC_KEYWORDS.filter(k => text.toLowerCase().includes(k));

  return {
    json: {
      ...item.json,
      async_level: asyncLevel,
      async_keywords_found: asyncKeywordsFound.join(', ')
    }
  };
}).filter(Boolean);

const DATA_ROLES_TITLE = [
  /data\s+analyst/i, /data\s+scientist/i, /business\s+intelligence/i,
  /\bbi\s+analyst/i, /marketing\s+analyst/i, /growth\s+analyst/i,
  /performance\s+marketing\s+analyst/i, /martech\s+analyst/i,
  /analytics\s+engineer/i, /reporting\s+analyst/i
];

const AI_ROLES_TITLE = [
  /ai\s+marketing/i, /ai\s+automation/i, /ai\s+workflow/i,
  /automation\s+specialist/i, /ai\s+specialist/i,
  /revenue\s+operations/i, /revops/i, /growth\s+hacker/i
];

const ADJ_ROLES = [
  /marketing/i, /data/i, /analytics/i, /reporting/i,
  /growth/i, /intelligence/i, /operations/i, /insights/i,
  /strategy/i, /performance/i, /digital/i, /crm/i
];

return $input.all().map(item => {
  const j = item.json;
  const titleText = j.job_title;
  const fullText = `${j.job_title} ${j.description} ${j.tags}`;

  // --- Taiwan eligibility score (0-40) ---
  let taiwanScore = 0;
  const locationText = `${j.location_text} ${j.description}`.toLowerCase();
  if (j.taiwan_eligible === 'yes') {
    if (/worldwide|work from anywhere|global remote|anywhere in the world/.test(locationText)) taiwanScore = 40;
    else if (/apac|contractor|deel|oyster|eor|employer of record/.test(locationText)) taiwanScore = 35;
    else taiwanScore = 30;
  } else if (j.taiwan_eligible === 'unclear') {
    if (j.location_risk === 'low') taiwanScore = 25;
    else if (j.location_risk === 'medium') taiwanScore = 20;
    else taiwanScore = 10;
  }

  // --- Async fit score (0-25) ---
  let asyncScore = 0;
  if (j.async_level === 'high') asyncScore = 25;
  else if (j.async_level === 'medium') asyncScore = 20;
  else if (/distributed|remote.first|fully\s+remote/i.test(fullText)) asyncScore = 15;
  else if (/remote/i.test(fullText)) asyncScore = 10;

  // --- Role fit score (0-25) ---
  let roleScore = 0;
  let roleCategory = 'other';

  if (DATA_ROLES_TITLE.some(p => p.test(titleText))) {
    roleScore = 25; roleCategory = 'data_analytics';
  } else if (AI_ROLES_TITLE.some(p => p.test(titleText))) {
    roleScore = 25; roleCategory = 'ai_marketing';
  } else if (DATA_ROLES_TITLE.some(p => p.test(fullText))) {
    roleScore = 20; roleCategory = 'data_analytics';
  } else if (AI_ROLES_TITLE.some(p => p.test(fullText))) {
    roleScore = 20; roleCategory = 'ai_marketing';
  } else if (ADJ_ROLES.some(p => p.test(titleText))) {
    roleScore = 15; roleCategory = 'adjacent';
  } else if (ADJ_ROLES.some(p => p.test(fullText))) {
    roleScore = 10; roleCategory = 'adjacent_indirect';
  }

  // --- Salary score (0-25) ---
  let salaryScore = 0;
  const salStr = (j.salary || '').replace(/,/g, '');
  const salMatch = salStr.match(/[\$£€]?([\d.]+)\s*[k]?/i);
  if (salMatch) {
    let num = parseFloat(salMatch[1]);
    if (/k/i.test(salStr)) num *= 1000;
    const monthly = num > 2000 ? num / 12 : num;
    if (monthly >= 5000) salaryScore = 25;
    else if (monthly >= 3000) salaryScore = 15;
    else salaryScore = 10;
  } else if (j.salary && j.salary.trim()) {
    salaryScore = 10;
  }

  const score = Math.min(100, taiwanScore + asyncScore + roleScore + salaryScore);

  // --- Why good fit ---
  const reasons = [];
  if (taiwanScore >= 35) reasons.push('Clearly worldwide/global remote');
  else if (taiwanScore >= 25) reasons.push('Likely Taiwan-eligible (low restriction)');
  if (asyncScore >= 20) reasons.push('Async-friendly culture');
  if (roleScore >= 20) reasons.push(`Strong role match: ${roleCategory.replace('_', ' ')}`);
  else if (roleScore >= 15) reasons.push(`Adjacent role: ${roleCategory.replace('_', ' ')}`);
  if (salaryScore >= 15) reasons.push('Good salary range');
  const whyGoodFit = reasons.join('; ') || 'Marginal match — review manually';

  return {
    json: {
      ...j,
      score,
      role_category: roleCategory,
      why_good_fit: whyGoodFit,
      date_found: new Date().toISOString().split('T')[0],
      application_status: 'new',
      notes: ''
    }
  };
});

return $input.all().map(item => {
  const j = item.json;
  const prompt = `Write a short cover letter for Jerry.

Jerry is based in Taiwan and wants async global remote work.

Jerry's background:
- Bilingual: English and Mandarin (grew up in California and Taiwan)
- Digital marketing background with data science bootcamp experience
- Technical: Python, SQL, Tableau, Power BI
- Marketing: Performance marketing, SEO, PPC, GA4, Meta Ads, Google Ads
- AI tools: ChatGPT, Claude, Gemini, Cursor
- Projects: dashboards, EDA, machine learning, customer segmentation, fraud detection, marketing analytics

Job being applied to:
Title: ${j.job_title}
Company: ${j.company}
Role category: ${j.role_category}
Why it fits Jerry: ${j.why_good_fit}
Score: ${j.score}/100

Write a cover letter that:
- Is under 220 words
- Mentions how Jerry can:
  * Reduce manual analysis time
  * Improve reporting speed
  * Connect marketing and data
  * Build AI-assisted workflows
  * Turn messy data into business action
- Is specific to this job title and company
- Tone: confident, direct, human, not desperate

Return ONLY the cover letter text. No subject line, no greeting wrapper.`;

  return {
    json: {
      _original_job: j,
      _cover_letter_prompt: prompt
    }
  };
});

return $input.all().map(item => {
  const coverText = item.json.choices?.[0]?.message?.content || 'Cover letter generation failed.';
  const originalJob = item.json._original_job || {};
  return {
    json: {
      ...originalJob,
      cover_letter_draft: coverText,
      alert_subject: `HIGH MATCH [${originalJob.score}/100]: ${originalJob.job_title} at ${originalJob.company}`,
      alert_body: `<h2>High-Score Job Alert 🎯</h2>
<p><b>Score: ${originalJob.score}/100</b></p>
<p><b>Role:</b> ${originalJob.job_title}</p>
<p><b>Company:</b> ${originalJob.company}</p>
<p><b>Taiwan Eligible:</b> ${originalJob.taiwan_eligible} — ${originalJob.taiwan_reason}</p>
<p><b>Async Level:</b> ${originalJob.async_level}</p>
<p><b>Timezone Risk:</b> ${originalJob.timezone_risk}</p>
<p><b>Salary:</b> ${originalJob.salary || 'Not listed'}</p>
<p><b>Why it fits Jerry:</b> ${originalJob.why_good_fit}</p>
<p><a href="${originalJob.job_url}">Apply Now →</a></p>
<hr>
<h3>Cover Letter Draft</h3>
<pre>${coverText}</pre>`
    }
  };
});

const allJobs = $input.all().map(i => i.json);
const today = new Date().toISOString().split('T')[0];

const topJobs = allJobs
  .filter(j => (j.score || 0) >= 70)
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 10);

const manualJobs = allJobs.filter(j =>
  j.taiwan_eligible === 'unclear' && (j.score || 0) >= 70
);

const rejected = allJobs.filter(j =>
  (j.score || 0) < 70 || j.ai_decision === 'reject'
);

// Rejection breakdown
const rejUS = rejected.filter(j => /us only|united states only|us residents/i.test(`${j.location_text} ${j.description}`)).length;
const rejEU = rejected.filter(j => /eu only|europe only|uk only|european union/i.test(`${j.location_text} ${j.description}`)).length;
const rejHybrid = rejected.filter(j => /hybrid|onsite|on-site/i.test(`${j.location_text} ${j.description}`)).length;
const rejTZ = rejected.filter(j => j.timezone_risk === 'high').length;
const rejScore = rejected.filter(j => (j.score || 0) < 70 && j.ai_decision !== 'reject').length;

// Top jobs HTML
const topSection = topJobs.length > 0
  ? topJobs.map((j, i) => `
<div style="border:1px solid #ddd;padding:12px;margin:8px 0;border-radius:6px;">
  <h3 style="margin:0 0 8px">${i + 1}. ${j.job_title}</h3>
  <p><b>Company:</b> ${j.company}</p>
  <p><b>Score:</b> <span style="color:${j.score >= 85 ? '#16a34a' : '#2563eb'}">${j.score}/100</span></p>
  <p><b>Taiwan Eligible:</b> ${j.taiwan_eligible === 'yes' ? '✅' : j.taiwan_eligible === 'unclear' ? '⚠️' : '❌'} ${j.taiwan_eligible} — ${j.taiwan_reason}</p>
  <p><b>Async Level:</b> ${j.async_level === 'high' ? '🟢' : j.async_level === 'medium' ? '🟡' : '🔴'} ${j.async_level}</p>
  <p><b>Timezone Risk:</b> ${j.timezone_risk}</p>
  <p><b>Salary:</b> ${j.salary || 'Not listed'}</p>
  <p><b>Why it fits Jerry:</b> ${j.why_good_fit}</p>
  <p><a href="${j.job_url}" style="color:#2563eb">Apply →</a></p>
</div>`).join('')
  : '<p>No jobs met the 70-point threshold today.</p>';

// Manual check section
const manualSection = manualJobs.length > 0
  ? manualJobs.map(j => `<li><b>${j.job_title}</b> at ${j.company} (Score: ${j.score}) — ${j.taiwan_reason} | <a href="${j.job_url}">View</a></li>`).join('')
  : '<li>None</li>';

// Build full digest
const htmlContent = `
<!DOCTYPE html>
<html>
<body style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto;padding:20px">

<h1 style="color:#1e3a5f">Daily Taiwan Eligible Async Remote Jobs</h1>
<p style="color:#666">${today} | ${topJobs.length} qualifying jobs out of ${allJobs.length} total reviewed</p>

<h2>Top Jobs Today</h2>
${topSection}

<h2>Manual Check Required</h2>
<p style="color:#666">These have unclear Taiwan eligibility but a good score. Review before skipping.</p>
<ul>${manualSection}</ul>

<h2>Rejected Today — Summary</h2>
<table style="border-collapse:collapse;width:100%">
  <tr style="background:#f5f5f5"><th style="padding:8px;text-align:left">Reason</th><th style="padding:8px;text-align:right">Count</th></tr>
  <tr><td style="padding:6px">US/Canada only</td><td style="padding:6px;text-align:right">${rejUS}</td></tr>
  <tr><td style="padding:6px">EU/Europe/UK only</td><td style="padding:6px;text-align:right">${rejEU}</td></tr>
  <tr><td style="padding:6px">Hybrid or onsite</td><td style="padding:6px;text-align:right">${rejHybrid}</td></tr>
  <tr><td style="padding:6px">High timezone risk</td><td style="padding:6px;text-align:right">${rejTZ}</td></tr>
  <tr><td style="padding:6px">Score below 70</td><td style="padding:6px;text-align:right">${rejScore}</td></tr>
  <tr style="font-weight:bold"><td style="padding:6px">Total rejected</td><td style="padding:6px;text-align:right">${rejected.length}</td></tr>
</table>

<p style="color:#999;font-size:12px;margin-top:30px">One sentence rule: I can do this job while living in Taiwan, without moving, without foreign work authorization, and without destroying my sleep schedule.</p>
</body>
</html>`;

return [{
  json: {
    digest_html: htmlContent,
    digest_subject: `Daily Remote Job Report — ${topJobs.length} matches — ${today}`,
    job_count: topJobs.length,
    total_reviewed: allJobs.length,
    high_score_count: topJobs.filter(j => j.score >= 85).length,
    today
  }
}];
